using System;

namespace Billiards.Physics
{
    /// <summary>
    /// Everything that defines a shot. This tiny struct is all that needs to be sent over
    /// the network, stored in a replay, or generated by the AI: the simulation is
    /// deterministic, so the same table state + the same CueStrike = the same outcome.
    /// </summary>
    [Serializable]
    public struct CueStrike
    {
        /// <summary>Aim heading in the table plane, radians. 0 = +X, PI/2 = +Z.</summary>
        public double Heading;
        /// <summary>Cue elevation above horizontal, radians (0 = level, ~0.5 jump, ~1.3 masse).</summary>
        public double Elevation;
        /// <summary>Cue tip speed at impact, m/s (0 .. PhysicsParams.MaxCueSpeed).</summary>
        public double Speed;
        /// <summary>Horizontal tip offset in units of R. +1 = right english (as seen by the shooter).</summary>
        public double SideOffset;
        /// <summary>Vertical tip offset in units of R. +1 = top (follow), -1 = bottom (draw).</summary>
        public double VerticalOffset;

        public CueStrike(double heading, double speed, double side = 0, double vertical = 0, double elevation = 0)
        {
            Heading = heading;
            Speed = speed;
            SideOffset = side;
            VerticalOffset = vertical;
            Elevation = elevation;
        }

        /// <summary>Unit vector along the cue, pointing from the butt towards the ball.</summary>
        public DVec3 CueDirection
        {
            get
            {
                var horizontal = new DVec3(Math.Cos(Heading), 0, Math.Sin(Heading));
                return horizontal * Math.Cos(Elevation) - DVec3.Up * Math.Sin(Elevation);
            }
        }

        public override string ToString() =>
            $"heading={Heading * 180 / Math.PI:F2}deg speed={Speed:F2} side={SideOffset:F2} vert={VerticalOffset:F2} elev={Elevation * 180 / Math.PI:F1}deg";
    }

    /// <summary>Velocity and spin given to the cue ball by a strike.</summary>
    public readonly struct StrikeResult
    {
        public readonly DVec3 Velocity;
        public readonly DVec3 AngularVelocity;
        public readonly bool Miscue;

        public StrikeResult(DVec3 velocity, DVec3 angularVelocity, bool miscue)
        {
            Velocity = velocity;
            AngularVelocity = angularVelocity;
            Miscue = miscue;
        }
    }

    /// <summary>
    /// Cue-tip / cue-ball impact model.
    ///
    /// The tip delivers an impulse J along the cue axis d at the contact point r
    /// (relative to the ball centre). Treating the cue as a free mass M colliding with
    /// restitution e, conservation of momentum and the off-centre lever arm give
    ///
    ///     J = (1 + e) * V0 / ( 1/M + 1/m + |r x d|^2 / I )
    ///     v = J d / m,      w = (r x J d) / I
    ///
    /// A centre hit with e = 1 reproduces the textbook v = 2 M V0 / (M + m).
    /// Off-centre hits lose a little speed (energy goes into spin), as in reality.
    ///
    /// Squirt: a real shaft deflects the cue ball away from the english side; we rotate
    /// the horizontal velocity by Dr. Dave's squirt angle, driven by the shaft end mass.
    /// Elevation tilts d downwards: the ball is driven into the slate and bounces (jump),
    /// and with side offset the spin axis tilts, so sliding friction curves the path (masse).
    /// </summary>
    public static class CueStrikeModel
    {
        public static StrikeResult Compute(in CueStrike strike, PhysicsParams p)
        {
            double R = p.BallRadius;
            double m = p.BallMass;
            double I = p.Inertia;

            // Clamp the tip offset to the miscue limit (a circle, not a square).
            double a = strike.SideOffset;
            double b = strike.VerticalOffset;
            double offset = Math.Sqrt(a * a + b * b);
            bool miscue = offset > p.MaxTipOffset + 1e-9;
            if (miscue)
            {
                a *= p.MaxTipOffset / offset;
                b *= p.MaxTipOffset / offset;
            }

            double speed = Math.Max(0, Math.Min(strike.Speed, p.MaxCueSpeed));

            DVec3 d = strike.CueDirection;
            // Shooter's frame: right = horizontal, perpendicular to d; up' completes the basis.
            DVec3 right = DVec3.Cross(DVec3.Up, d).Normalized;
            DVec3 upPrime = DVec3.Cross(d, right);

            // Contact point on the sphere surface, on the side facing the cue.
            double c = Math.Sqrt(Math.Max(0, 1 - a * a - b * b));
            DVec3 r = (right * a + upPrime * b - d * c) * R;

            DVec3 rxd = DVec3.Cross(r, d);
            double j = (1 + p.TipRestitution) * speed / (1 / p.CueMass + 1 / m + rxd.LengthSq / I);
            if (miscue) j *= 0.4; // tip slides off: weak, unpredictable hit

            DVec3 impulse = d * j;
            DVec3 v = impulse / m;
            DVec3 w = DVec3.Cross(r, impulse) / I;

            // Squirt (cue ball deflection) — only meaningful for the horizontal part.
            if (Math.Abs(a) > 1e-9)
            {
                double x = Math.Abs(a);
                double tanSquirt = 2.5 * x * Math.Sqrt(1 - x * x)
                                   / (1 + m / p.CueEndMass + 2.5 * (1 - x * x));
                double squirt = Math.Atan(tanSquirt);
                // Right english (a > 0) pushes the ball to the shooter's left.
                // right = Up x d = (dZ, 0, -dX), and RotateY by +angle turns a heading
                // towards (-dZ, 0, dX) = -right, i.e. to the left. So +angle = left.
                double angle = a > 0 ? squirt : -squirt;
                v = DVec3.RotateY(v.Horizontal, angle) + new DVec3(0, v.Y, 0);
            }

            return new StrikeResult(v, w, miscue);
        }
    }
}
